package main
import("context";"crypto/sha256";"encoding/hex";"encoding/json";"fmt";"os";"github.com/ertyoii/transit-routing-go/walking/graph";"github.com/ertyoii/transit-routing-go/walking/osm")
func main(){b,e:=os.ReadFile("osm-pedestrian-graph.json");if e!=nil{panic(e)};h:=sha256.Sum256(b);var raw struct{Source string `json:"source_sha256"`;Policy string `json:"permission_policy"`};if e=json.Unmarshal(b,&raw);e!=nil{panic(e)};f,e:=os.Open("osm-pedestrian-graph.json");if e!=nil{panic(e)};defer f.Close();g,e:=osm.Load(context.Background(),f,osm.Options{MaxBytes:int64(len(b)),ExpectedGraphSHA256:hex.EncodeToString(h[:]),ExpectedSourceSHA256:raw.Source,PermissionPolicy:raw.Policy,Limits:graph.DefaultLimits()});if e!=nil{panic(e)};out,_:=json.MarshalIndent(g.Descriptor(),"","  ");fmt.Println(string(out))}
